        let bInputs = Inputs.vectors(H.Vector.self, seed: 0x19E2_66B1_E0FC_4E51)
        let cInputs = Inputs.vectors(H.Vector.self, seed: 0x19E2_63B1_E0FC_4938)
        let dInputs = Inputs.vectors(H.Vector.self, seed: 0x19E2_64B1_E0FC_4AEB)
        for (a, b, c, d) in mixedQuadruples(
            aInputs,
            bInputs,
            cInputs,
            dInputs,
            seed: 0x6195_A9F1_7CDE_733A
        ) {
            let (_, portLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                unsafe H.appendInterleaved4(a, b, c, d, toUnchecked: &output)
            }
            let (_, referenceLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                H.appendInterleaved4(a, b, c, d, to: &output)
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c)), d: \(describe(d))"
            )
        }
        mismatches.record()
    }
}
